CREATE TABLE training_categories(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE training_courses(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,description TEXT,required BOOLEAN NOT NULL,pass_mark NUMERIC(5,2) NOT NULL CHECK(pass_mark BETWEEN 0 AND 100),maximum_score NUMERIC(8,2) NOT NULL CHECK(maximum_score>0),duration_minutes INT CHECK(duration_minutes>0),validity_months INT CHECK(validity_months>0),instructor VARCHAR(255),active BOOLEAN NOT NULL DEFAULT TRUE,category_id UUID REFERENCES training_categories(id));